import { useEffect, useState, type FormEvent } from 'react'
import {
  createExpense,
  fetchExpenses,
  ValidationError,
  type Expense,
} from './api'

export function App() {
  const [expenses, setExpenses] = useState<Expense[] | null>(null)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    const controller = new AbortController()
    fetchExpenses(controller.signal)
      .then(setExpenses)
      .catch((e: unknown) => {
        if (controller.signal.aborted) return
        setLoadError(e instanceof Error ? e.message : 'Failed to load expenses')
      })
    return () => controller.abort()
  }, [])

  async function onSubmit(e: FormEvent) {
    e.preventDefault()
    if (submitting) return
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      const created = await createExpense({
        label,
        amount: Number(amount),
        currency,
      })
      setExpenses((prev) => [...(prev ?? []), created])
      setLabel('')
      setAmount('')
    } catch (err) {
      if (err instanceof ValidationError) setErrors(err.errors)
      else
        setFormError(err instanceof Error ? err.message : 'Submission failed')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <main>
      <h1>My expenses</h1>

      {loadError && <p role="alert">{loadError}</p>}
      {!loadError && expenses === null && <p>Loading…</p>}
      {expenses !== null &&
        (expenses.length === 0 ? (
          <p>No expenses yet.</p>
        ) : (
          <ul>
            {expenses.map((x) => (
              <li key={x.id}>
                {x.label} — {x.amount} {x.currency} ({x.status})
              </li>
            ))}
          </ul>
        ))}

      <h2>New expense</h2>
      <form onSubmit={onSubmit} noValidate>
        <Field id="label" name="Label" error={errors.label}>
          <input
            id="label"
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            aria-invalid={!!errors.label}
            aria-describedby={errors.label ? 'label-error' : undefined}
          />
        </Field>
        <Field id="amount" name="Amount" error={errors.amount}>
          <input
            id="amount"
            type="number"
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            aria-invalid={!!errors.amount}
            aria-describedby={errors.amount ? 'amount-error' : undefined}
          />
        </Field>
        <Field id="currency" name="Currency" error={errors.currency}>
          <input
            id="currency"
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
            aria-invalid={!!errors.currency}
            aria-describedby={errors.currency ? 'currency-error' : undefined}
          />
        </Field>
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>
    </main>
  )
}

function Field(props: {
  id: string
  name: string
  error?: string
  children: React.ReactNode
}) {
  return (
    <div>
      <label htmlFor={props.id}>{props.name}</label>
      {props.children}
      {props.error && (
        <span id={`${props.id}-error`} role="alert">
          {props.error}
        </span>
      )}
    </div>
  )
}
